try:
    f1_num = int(assign['f1_num']); f1_den = int(assign['f1_den'])
    f2_num = int(assign['f2_num']); f2_den = int(assign['f2_den'])
    u1 = int(assign['u1']); v1 = int(assign['v1'])
    u2 = int(assign['u2']); v2 = int(assign['v2'])
    g_num = int(assign['g_num']); g_den = int(assign['g_den'])
    w = float(assign['w'])
    m = int(assign['m'])
except Exception:
