    return (False, None)
# basic checks
if f1_den <= 0 or f2_den <= 0 or g_den <= 0 or m <= 0:
    # invalid denominators or m
    return (False, None)
t1 = Fraction(f1_num, f1_den)
t2 = Fraction(f2_num, f2_den)
g = Fraction(g_num, g_den)
if not (Fraction(0,1) < t1 < Fraction(1,1) and Fraction(0,1) < t2 < Fraction(1,1) and Fraction(0,1) < g < Fraction(1,1)):
    # invalid fractions
    return (False, None)
if u1 <= 0 or v1 <= 0 or u2 <= 0 or v2 <= 0:
    # invalid ratios
    return (False, None)
r1 = Fraction(u1, u1+v1)
r2 = Fraction(u2, u2+v2)
if not (Fraction(0,1) < r1 < Fraction(1,1) and Fraction(0,1) < r2 < Fraction(1,1)):
    # invalid area ratios
    return (False, None)
# compute q from both constraints: q = (r - t^2) / (2*(t - r))
try:
    q1 = (r1 - t1*t1) / (2*(t1 - r1))
    q2 = (r2 - t2*t2) / (2*(t2 - r2))
except ZeroDivisionError:
    return (False, None)
if q1 <= 0 or q2 <= 0:
    return (False, None)
# enforce consistency of the two constraints
if q1 != q2:
    # inconsistent instance
    return (False, None)
q = q1
# determine D from w and g: w = D*(q + g)
q_float = float(q)
D = w / (q_float + float(g))
if D <= 0:
    return (False, None)
# equal-area t satisfies: t^2 + 2 q t - (2 q + 1)/2 = 0
disc = 4.0*q_float*q_float + 4.0*q_float + 2.0
if disc <= 0:
    return (False, None)
t_eq = (-2.0*q_float + math.sqrt(disc)) / 2.0
if not (0.0 < t_eq < 1.0):
    return (False, None)
x = D * (q_float + t_eq)
ans = int(math.floor((x*x)/m))
# difficulty guard: avoid trivial tiny answers
if ans < 10:
    return (False, None)
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

